package io.knowledgebrain.activity;
import org.junit.jupiter.api.Test;import java.util.*;import java.time.*;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
class ActivityQueryTest extends ActivityFixtures {
 static Map<String,String[]> params(String... p){var m=new HashMap<String,String[]>();for(int i=0;i<p.length;i+=2)m.put(p[i],new String[]{p[i+1]});return m;}
 @Test void inclusiveLocalDaysHonorDstInsteadOfAssumingTwentyFourHours(){var s=id();for(var p:List.of(params("from","2026-03-08","to","2026-03-08","timezone","America/New_York"),params("from","2026-11-01","to","2026-11-01","timezone","America/New_York"))){var q=ActivityQuery.parse(s,p);assertEquals(p.get("from")[0].endsWith("03-08")?23:25,(q.to()-q.from())/3600000);}assertEquals(20,ActivityQuery.parse(s,Map.of()).limit());}
 @Test void cursorIsBoundToSpaceFiltersAndOrderingKey(){var s=id();var p=params("kind","ROADMAP","timezone","Asia/Seoul","limit","1");var q=ActivityQuery.parse(s,p);var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("ROADMAP"),wire("ROADMAP",s));String cursor=q.cursor(e);p.put("before",new String[]{cursor});var next=ActivityQuery.parse(s,p);assertEquals(e.eventId(),next.event());assertEquals(Instant.parse(e.occurredAt()).toEpochMilli(),next.before());assertThrows(ResponseStatusException.class,()->ActivityQuery.parse(id(),p));p.put("kind",new String[]{"PROGRESS"});assertThrows(ResponseStatusException.class,()->ActivityQuery.parse(s,p));}
 @Test void malformedDuplicateUnknownAndUnboundedQueryInputsFail(){var s=id();for(var p:List.of(params("unknown","x"),params("from","2026-10-01"),params("timezone","bad/zone"),params("limit","0"),params("limit","101"),params("kind","UNKNOWN"),params("before","A"),params("from","2026-02-30","timezone","UTC"),params("from","2026-10-15","to","2026-10-14","timezone","UTC"),params("from","2024-01-01","to","2026-01-01","timezone","UTC")))assertThrows(ResponseStatusException.class,()->ActivityQuery.parse(s,p));assertThrows(ResponseStatusException.class,()->ActivityQuery.parse(s,Map.of("limit",new String[]{"1","2"})));}
}
